//! Keyword/intent shortcuts for about-app and clearly off-scope questions.
//! These replies are hardcoded — never generated by the LLM.
//!
//! Policy: **conservative**. Only clear About / clear OutOfScope phrases are
//! intercepted. Ambiguous messages fall through to RAG+LLM.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StaticIntent {
    AboutApp,
    OutOfScope,
}

const ABOUT_REPLY: &str = "Men Faqih AI by MOND — O‘zbekiston qonunchiligi bo‘yicha to‘liq oflayn yuridik yordamchiman. Hozircha Mehnat kodeksi va Fuqarolik kodeksi doirasida ishlayman. Internetga ulanish shart emas.";

const OUT_OF_SCOPE_REPLY: &str = "Faqih AI faqat Mehnat kodeksi va Fuqarolik kodeksi bo‘yicha savollarga javob beradi. Umumiy mavzular yoki internetdan ma’lumot izlash men uchun mavjud emas — bu oflayn model.";

/// Slightly longer copy for Settings → Dastur haqida (kept in sync with chat About reply).
pub const ABOUT_PAGE_TEXT: &str = "Faqih AI by MOND — O‘zbekiston qonunchiligi bo‘yicha desktop yuridik yordamchi. Dastur 100% oflaynda ishlaydi: bulutli AI yo‘q, internet talab qilinmaydi. Hozirgi qamrov: Mehnat kodeksi va Fuqarolik kodeksi. Bu yuridik maslahat o‘rnini bosmaydi — manbalarni tekshiring.";

pub fn static_reply(intent: StaticIntent) -> &'static str {
    match intent {
        StaticIntent::AboutApp => ABOUT_REPLY,
        StaticIntent::OutOfScope => OUT_OF_SCOPE_REPLY,
    }
}

/// Normalize for matching: lowercase, fold common apostrophes, collapse spaces.
fn normalize(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    let mut prev_space = false;
    for ch in input.chars() {
        let c = match ch {
            '‘' | '’' | '`' | '\u{02BB}' | '\u{02BC}' => '\'',
            _ => ch,
        };
        let c = c.to_lowercase().next().unwrap_or(c);
        if c.is_whitespace() {
            if !prev_space && !out.is_empty() {
                out.push(' ');
                prev_space = true;
            }
        } else {
            out.push(c);
            prev_space = false;
        }
    }
    out.trim().to_string()
}

fn contains_any(hay: &str, needles: &[&str]) -> bool {
    needles.iter().any(|n| hay.contains(n))
}

